QCU_T("es", "ethiqueLegislation", {
  "0": ["¿Cómo calificar el antiguo modelo de comunicación asistencial, anterior al consentimiento a los cuidados y al paciente socio autónomo?",["Un modelo paternalista, en el que el profesional decide por el paciente.","Un modelo de colaboración, centrado en un paciente autónomo.","Un modelo autonomista, fundado en el consentimiento del paciente."],["El antiguo modelo era paternalista: el profesional decidía en lugar del paciente.","El paciente socio corresponde al modelo reciente, no al antiguo.","La autonomía y el consentimiento surgieron después: no caracterizan el antiguo modelo."]],
  "1": ["El encarnizamiento terapéutico comprende:",["Prolongar artificialmente la vida.","Proteger los derechos de los pacientes","Una muerte digna"],["El curso lo asimila a la obstinación irrazonable: el paciente con una afección incurable sufre tratamientos que solo prolongan dolorosamente su agonía.","Es precisamente lo contrario: la obstinación irrazonable atenta contra la dignidad y el bienestar del paciente.","La muerte digna se obtiene renunciando a la obstinación irrazonable; es su contrario, no su definición."]],
  "2": ["¿Quién puede consentir al tratamiento médico en un menor de más de 16 años?",["El médico","El propio menor","El padre únicamente"],["El profesional valora la capacidad del menor entre los 12 y los 16 años, pero nunca consiente en lugar del paciente.","A partir de los 16 años se reputa al menor capaz de consentir por sí solo; el consentimiento por representación deja de ser la regla.","Antes de los 16 años el consentimiento lo dan los representantes legales, en plural, y no uno solo de los progenitores."]],
  "3": ["¿Qué es el «sufrimiento grave, crónico e imposibilitante» según la ley de eutanasia?",["Todo dolor moderado","Una enfermedad leve pero crónica","Un dolor constante, imposibilitante e intolerable"],["Un dolor moderado sigue siendo accesible a los tratamientos y no cumple el criterio exigido.","La cronicidad no basta: la afección debe ser grave e incurable y comprometer el pronóstico vital.","La ley exige un sufrimiento ligado a la afección, refractario a los tratamientos o insoportable según el propio paciente."]],
  "4": ["¿Cuál es el criterio principal para la asistencia médica urgente de un menor?",["El interés superior del menor","La elección de los padres","La voluntad del médico"],["El curso establece que el interés superior del menor prevalece sobre cualquier otro interés legítimo.","La voluntad parental cede cuando se opone al interés superior del menor, en particular en una urgencia vital.","El profesional actúa bajo el principio de beneficencia en beneficio del paciente; no impone su propia voluntad."]],
  "5": ["¿Qué condición no es necesaria para solicitar la ayuda para morir?",["Ser mayor de edad","Tener una enfermedad leve","Ser residente legal"],["La mayoría de edad figura entre las cinco condiciones de acceso a la ayuda para morir que enumera el curso.","La ley exige al contrario una afección grave e incurable que comprometa el pronóstico vital, en fase avanzada o terminal.","La residencia regular y estable forma parte de las condiciones de acceso que prevé la ley."]],
  "6": ["La negativa parental a un tratamiento vital para un menor:",["Debe respetarse","Debe aprobarla un juez de inmediato","Constituye una situación de riesgo"],["El respeto de la decisión parental cede ante el deber de asistencia y el estado de necesidad.","El profesional debe actuar primero para salvaguardar la vida; la intervención judicial no condiciona la actuación urgente.","La negativa de los representantes legales a un tratamiento necesario para salvaguardar la vida se trata como una situación de riesgo, que se comunica para que se tome una decisión en el interés del menor."]],
  "7": ["En el delito de revelación de secretos…",["La información privada del paciente debe protegerse siempre.","Un profesional sanitario incurrirá en la misma pena que un ciudadano.","El simple acceso a la historia clínica se considera un delito grave."],["La confidencialidad cubre toda información conocida con ocasión de la asistencia, sin límite de tiempo ni de objeto.","La condición de profesional sanitario es al contrario una circunstancia agravante, al ser el secreto una obligación ligada a la función.","Lo que se castiga es la revelación o el acceso no autorizado, no el acceso legítimo de un profesional que participa en la asistencia."]],
  "8": ["En caso de error de diagnóstico, hay responsabilidad si:",["El diagnóstico es correcto pero mal explicado","No se han realizado las pruebas necesarias","El tratamiento no era eficaz"],["Un defecto de explicación corresponde al deber de información, no al error de diagnóstico.","Omitir las pruebas que imponía la lex artis constituye un incumplimiento del deber de diligencia, es decir una imprudencia que compromete la responsabilidad.","La asistencia constituye una obligación de medios: la ausencia de resultado no es en sí culposa."]],
  "9": ["¿Qué es la lex artis en la responsabilidad sanitaria?",["Una ley específica","Una norma de ética","Una práctica reconocida científicamente"],["No es un texto legal, sino un estándar profesional al que se remiten los jueces.","Corresponde al saber técnico y no al ámbito normativo de la ética.","La lex artis designa el conjunto de las reglas del arte admitidas por la ciencia, cuyo respeto condiciona la exoneración de responsabilidad."]],
  "10": ["¿Qué diferencia existe entre la responsabilidad contractual y la extracontractual?",["El tipo de relación entre paciente y profesional","La edad del paciente","El lugar de la intervención"],["El curso opone la relación contractual, nacida del recurso a los servicios del profesional, a la relación extracontractual, en la que ningún contrato vincula a las partes.","La edad no entra en la calificación del vínculo jurídico entre profesional y paciente.","El lugar no determina la naturaleza del vínculo: tanto una como otra puede darse en un centro o en la consulta."]],
  "11": ["La responsabilidad civil nace cuando hay:",["Buena fe","Daño causado por negligencia","Contrato escrito"],["La buena fe no crea ninguna obligación de reparar; al contrario, puede atenuar la apreciación de la culpa.","Supone una acción negligente, una culpa y un perjuicio que debe repararse mediante una indemnización.","La responsabilidad puede ser extracontractual, sin que ningún escrito vincule a las partes."]],
  "12": ["En la mayoría de sus intervenciones en materia de Salud, la obligación del profesional es:",["Una obligación de resultados","La obligación de proponer únicamente el mejor tratamiento, según el criterio del médico","Una obligación de medios"],["No se compromete ninguna responsabilidad cuando las técnicas disponibles se han empleado correctamente, incluso sin curación.","El criterio no es la preferencia personal del profesional, sino la conformidad con la lex artis.","El curso enuncia que la asistencia sanitaria constituye una obligación de medios y no de resultados."]],
  "13": ["Un profesional sanitario puede negar la asistencia únicamente si:",["Existe un riesgo real y objetivo para él","No está de acuerdo con el paciente","No dispone de material"],["El curso reserva el abandono de los pacientes al solo caso de un riesgo grave, real y objetivo para la persona del profesional.","El desacuerdo no autoriza la negativa a asistir; el profesional debe garantizar la asistencia urgente.","La falta de material obliga a derivar al paciente, no a negar toda asistencia."]],
  "14": ["¿En qué consiste la despersonalización de la historia clínica?",["En no incluir anotaciones personales referidas al paciente","En eliminar de la historia clínica entregada a docentes o investigadores los datos que no les son necesarios","En omitir las patologías anteriores del paciente que no están relacionadas con la enfermedad actual"],["Las anotaciones subjetivas sí figuran en la historia; solo son objeto de reserva cuando el paciente accede a ella.","El acceso con fines de investigación o de docencia obliga a separar los datos de identificación de los datos clínicos para garantizar el anonimato.","La historia debe al contrario seguir siendo fiable y completa para permitir conocer el estado de salud real."]],
  "15": ["¿Quién controla el proceso de eliminación de las anotaciones subjetivas de las historias clínicas?",["El paciente, si lo exige","El superior del profesional que las ha escrito","El profesional que las ha escrito"],["El derecho de acceso del paciente se detiene precisamente ante la reserva de las anotaciones subjetivas.","La reserva es un derecho propio del autor de las anotaciones, no una prerrogativa jerárquica.","El curso reconoce a los profesionales que han participado en la elaboración de la historia el derecho a oponer la reserva de sus anotaciones subjetivas."]],
  "16": ["La prescripción de eutanasia puede realizarla:",["El médico responsable","Cualquier enfermera","El equipo asistencial entero"],["La ley encomienda la conducción del procedimiento al médico responsable: es él quien recibe la solicitud, verifica las condiciones y prescribe.","El profesional de enfermería interviene en particular para verificar la confirmación de la voluntad del paciente, pero no prescribe.","El equipo se asocia al procedimiento y a la verificación colegiada, sin que la prescripción sea un acto colectivo."]],
  "17": ["¿Funciones de un fisioterapeuta propietario de una clínica frente a las historias clínicas, según la Ley Orgánica de Protección de Datos?",["Debe garantizar la seguridad y la conservación de las historias","Debe cumplimentar la historia clínica y revisar el trabajo de los fisioterapeutas que trabajan bajo su responsabilidad","Debe garantizar la seguridad y la conservación de las historias y revisar el trabajo de los fisioterapeutas bajo su responsabilidad"],["La Ley Orgánica de Protección de Datos pone a cargo del responsable del tratamiento la seguridad de los datos personales y su conservación; es la única obligación que se deriva de ese texto.","Cumplimentar la historia y supervisar al equipo son deberes clínicos y jerárquicos, ajenos a la ley de protección de datos.","La propuesta mezcla una obligación derivada de la LOPD con una función de supervisión que no se deriva de ella; la pregunta versa únicamente sobre el fundamento de esa ley."]],
  "18": ["¿Cuál es la pena por no socorrer a una persona en peligro manifiesto sin riesgo para uno mismo?",["6 meses de prisión","1 año de prisión","De 3 a 12 meses de multa"],["La privación de libertad se reserva a las formas agravadas, no a la simple negativa a asistir.","Una pena de prisión supone una circunstancia agravante, como haber causado uno mismo el peligro.","El curso remite al código penal, que castiga con multa la simple negativa a socorrer a una persona en peligro manifiesto y grave."]],
  "19": ["La objeción de conciencia de un profesional sanitario debe ser:",["Anticipada y por escrito","Verbal","Aceptada por el médico responsable"],["La objeción de conciencia debe declararse por anticipado y por escrito, para que la organización pueda garantizar la continuidad de la asistencia.","Una declaración oral no permite fechar la objeción ni organizar la sustitución del profesional.","La objeción es un derecho propio del profesional: no está sometida a la autorización de un colega."]],
  "20": ["¿Cuál es la pena para un conductor que abandona a una víctima de accidente sin justificación?",["3 meses de multa","Hasta 4 años de prisión","Ninguna si no hay testigos"],["La multa sanciona la negativa a socorrer ordinaria, no la del causante del accidente.","Haber causado uno mismo el accidente agrava el delito de omisión del deber de socorro y eleva la sanción de la multa a la prisión.","La ausencia de testigos no suprime la infracción: lo que se castiga es la indiferencia ante el peligro."]],
  "21": ["En el delito de omisión del deber de socorro…",["No existen distintos tipos de castigo en ese delito.","No tendrá ninguna obligación si no sabe cómo ayudar.","El bien jurídico protegido es la solidaridad humana."],["La sanción varía según las circunstancias, en particular cuando el autor ha provocado él mismo el peligro.","El curso precisa que la conducta sigue siendo punible incluso si la ayuda hubiera resultado inútil; hay que al menos avisar a los servicios de emergencia.","El curso presenta la asistencia a una persona en peligro como una obligación moral, legal y deontológica que se impone a todo ciudadano: lo que se protege es la solidaridad."]],
  "22": ["¿Cuándo se considera que no se ha cometido ningún delito de intrusismo?",["Cuando un profesional realiza actividades que no pertenecen exclusivamente a su profesión","Cuando un profesional ejerce una profesión sin titulación","Cuando un profesional realiza sin supervisión actividades reservadas a profesionales que exceden sus competencias"],["El intrusismo supone invadir actos reservados: una actividad no exclusiva puede realizarse sin cometer la infracción.","Ejercer sin título es el caso más característico del intrusismo profesional, que la deontología obliga a denunciar.","Exceder las propias competencias en actos reservados constituye precisamente intrusismo."]],
  "23": ["¿Qué funciones debe asumir el trabajador por cuenta ajena frente a las historias clínicas?",["Respetar el carácter confidencial de la historia clínica","Respetar el carácter confidencial de la historia clínica y cumplimentarla de forma legible","Cumplimentar la historia clínica de forma legible"],["Exacto pero incompleto: la confidencialidad no exime de cumplimentar efectivamente la historia.","Ambos deberes se acumulan: el secreto profesional protege el contenido, y el paciente tiene derecho a que se consigne información fiable y actualizada.","Exacto pero incompleto: llevar la historia no dice nada de la obligación de secreto que protege su contenido."]],
  "24": ["¿Qué es un valor?",["Lo que una persona o una comunidad juzga lo bastante importante para buscarlo","Una regla de conducta que la conciencia moral tiene por obligatoria","Una prerrogativa reconocida a toda persona por su condición humana"],["El valor se define por la importancia que se reconoce a algo, lo que justifica que se promueva y se privilegie.","Esa es la definición de la norma moral, que se deriva del valor sin confundirse con él.","Esa es la definición de un derecho; el valor le es anterior y le sirve de fuente."]],
  "25": ["¿Cuál de estas propuestas no corresponde a una forma que puede adoptar un valor?",["Un estado de ánimo buscado por sí mismo, como la paz o la seguridad","Una sanción dictada por la autoridad en caso de incumplimiento de la norma","Una conducta como decir la verdad o proteger a los más vulnerables"],["Un estado mental buscado por sí mismo es efectivamente una de las formas del valor.","La sanción corresponde al derecho y no es una forma que revista el valor.","Una conducta derivada de un objeto o de un estado mental se cuenta entre esas formas."]],
  "26": ["¿Cuál es el papel de los valores en la toma de decisión?",["Aportar una respuesta directa y univoca a cada dilema que se plantee","Eximir de analizar la situación aplicando una regla ya fijada","Ayudar a reflexionar y a jerarquizar las prioridades, sin zanjar el dilema"],["Si así fuera, ningún conflicto de valores sería posible y la deliberación resultaría inútil.","Ese es el funcionamiento de la norma moral seguida sin examen, no el del valor.","Son herramientas de reflexión: iluminan las soluciones posibles sin decidir en lugar del profesional."]],
  "27": ["¿De dónde proceden los valores de una persona?",["De la familia, de la religión, del medio social, de la educación y del género","Únicamente de la educación recibida en la infancia, y después permanecen fijos","Únicamente del marco legal vigente en el país donde la persona reside"],["Esas influencias cruzadas construyen los valores personales, cuya jerarquía se desplaza a lo largo de la vida.","La importancia que se concede a los valores personales evoluciona a lo largo de toda la existencia.","La ley encuadra las conductas, pero no constituye el origen de los valores individuales."]],
  "28": ["¿Qué es un conflicto de valores?",["La oposición entre un valor personal y una disposición legal vigente","La oposición, en una situación dada, de dos valores igualmente legítimos","La incapacidad de una persona de identificar cuáles son sus propios valores"],["Esa es la divergencia entre ética y legalidad, que constituye otra configuración.","Como ambos merecen ser respetados, se necesita un análisis profundo para determinar la conducta que hay que seguir.","La incertidumbre no es un conflicto: este supone dos valores identificados y opuestos."]],
  "29": ["¿Por qué exige un conflicto de valores un análisis profundo?",["Siempre existe un valor superior y basta con conseguir identificarlo","La ley designa en cada caso el valor que debe prevalecer sobre el otro","Ningún valor prima de forma absoluta, y debe respetarse la pluralidad cultural"],["Precisamente, ningún valor absoluto prevalece sobre los demás en todas las circunstancias.","La ley suele callar o resultar ambigua sobre esos arbitrajes, lo que vuelve necesaria la reflexión.","La ausencia de jerarquía absoluta y la coexistencia de escalas de valores diferentes impiden toda solución automática."]],
  "30": ["¿Cuál es la relación entre los valores y los derechos?",["No son lo mismo, pero los valores están en el origen de los derechos","Son dos términos equivalentes que designan exactamente la misma realidad","Son los derechos reconocidos los que generan los valores de una sociedad"],["Los derechos formalizan jurídicamente lo que los valores han señalado antes como importante.","Confundirlos equivaldría a ignorar que el valor precede al reconocimiento jurídico.","El orden es el inverso: es el valor reconocido el que impulsa a crear el derecho correspondiente."]],
  "31": ["¿Qué se busca al hablar de valores universales?",["Los valores mayoritarios en los países más poblados del planeta","Lo que vale para todos los individuos en virtud de nuestra humanidad compartida","Los valores impuestos a los Estados por los tratados que han ratificado"],["Una mayoría estadística no fundamenta la universalidad, que se apoya en la humanidad común.","La universalidad se apoya en lo que es común a la humanidad, más allá de los contextos particulares.","El valor universal precede al instrumento jurídico, que no hace más que expresarlo."]],
  "32": ["¿Qué significa la etimología de la palabra «moral»?",["Viene del griego *ethos*, que designa el carácter de una persona","Viene del latín *norma*, que designa la regla y la escuadra","Viene del latín *mores*, que designa las costumbres de una sociedad"],["Esa es la etimología de «ética», que remite a la reflexión sobre las costumbres más que a las costumbres mismas.","La norma designa la regla que produce la moral, no el origen de la palabra en sí.","La moral es el conjunto de las normas y reglas de conducta propias de una sociedad dada."]],
  "33": ["¿De dónde se deriva el carácter obligatorio de la norma moral?",["Del valor que nosotros mismos le reconocemos","De una ley que la impone y prevé una sanción","De la autoridad de quien la ha formulado"],["La obligación moral no viene de una coacción exterior, sino de la adhesión al valor que traduce.","Ese es el mecanismo de la regla jurídica, cuya fuerza viene de la coacción pública.","Si la obligación dependiera de la autoridad de su autor, sería disciplinaria y no moral."]],
  "34": ["¿Cuál de estas afirmaciones sobre la moral es correcta?",["Solo existe una, idéntica en todo tiempo y en todo lugar","No existe una sola: las prácticas varían según las épocas y los lugares","Solo atañe a la esfera privada y nunca a las conductas sociales"],["La historia muestra al contrario una pluralidad de morales según las épocas y las sociedades.","Lo que se tenía por correcto en la Antigüedad puede juzgarse inaceptable hoy.","La moral versa precisamente sobre las reglas de conducta propias de una sociedad."]],
  "35": ["¿Qué actitud caracteriza a la persona que se limita a seguir la moral de su entorno?",["Cuestiona las reglas, delibera y después elige libremente ajustarse a ellas","Rechaza las reglas establecidas en nombre de sus convicciones personales","Conoce las reglas y las acepta de inmediato, sin interponer reflexión alguna"],["Ese recorrido reflexivo define al contrario el proceder ético.","El rechazo supone también una toma de posición, y por tanto un examen previo.","Esa adhesión sin examen es propia de la moral, a la que se suscribe sin interrogarla."]],
  "36": ["¿Por qué se dice que la moral es heterónoma y la ética autónoma?",["La moral recibe su ley de fuera, y la ética la extrae de sí misma por deliberación","La moral atañe al individuo aislado, y la ética implica siempre a un colectivo","La moral se transmite por escrito, y la ética se transmite oralmente"],["La heteronomía designa la regla recibida del exterior, y la autonomía la que el sujeto se da a sí mismo.","Es más bien lo contrario: la moral la comparte un grupo, y la reflexión la sostiene el sujeto.","La distinción no depende del soporte, sino del origen de la obligación."]],
  "37": ["¿En qué momento surge la ética?",["Cuando una autoridad reconocida codifica por escrito las reglas de un grupo","Cuando una mediación reflexiva se interpone entre el individuo y la norma recibida","Cuando una sociedad alcanza un consenso unánime sobre el bien y el mal"],["La codificación produce una deontología o un derecho, no el proceder reflexivo que es la ética.","Nace cuando el individuo deja de seguir la regla sin discutirla y pone a prueba la moral vigente.","Un consenso admitido sin examen corresponde todavía a la moral."]],
  "38": ["¿Cómo se distinguen la moral y la ética en su relación con el tiempo?",["La moral se transforma sin cesar, y la ética fija principios inmutables","Ambas evolucionan al mismo ritmo y según los mismos mecanismos","La moral se presenta como inmutable, y la ética conduce a una reflexión dinámica"],["La inversión es completa: es la moral la que se presenta como estable y universalmente válida.","Su diferencia radica precisamente en que una se da como establecida y la otra como cuestionadora.","La ética obliga a preguntarse si lo que se tiene por bueno lo es realmente, lo que vuelve su cuestionamiento siempre situado."]],
  "39": ["¿Cómo comenzó la reflexión ética en Occidente?",["Por la constatación de que lo que estaba bien visto en una ciudad estaba mal visto en otra","Por la codificación escrita de las reglas de conducta propias de cada ciudad","Por la formulación de las primeras reglas de la relación entre profesional y enfermo"],["Ese relativismo llevó a ver la moral como una simple convención y a negar los principios universales.","La puesta por escrito de las reglas produce derecho, no el despertar de la reflexión ética.","Esas reglas profesionales corresponden a la deontología médica, posterior a ese despertar."]],
  "40": ["¿En qué consiste la mayéutica empleada frente al relativismo moral?",["Demostrar mediante un razonamiento continuo que ciertas reglas valen en todas partes","Llevar al interlocutor, mediante preguntas, a examinar de forma crítica sus ideas","Recopilar las costumbres de las ciudades para extraer de ellas los puntos comunes"],["El método procede por interrogación y no por demostración impuesta desde fuera.","El cuestionamiento lo lleva a distinguir lo que tiene valor de lo que hay que rechazar por carecer de fundamento.","Esa descripción comparativa es justamente lo que había conducido al relativismo que se trata de superar."]],
  "41": ["¿Qué es la ética clínica?",["El conjunto de las reglas disciplinarias impuestas a una profesión sanitaria","El estudio de las consecuencias jurídicas de las faltas cometidas con ocasión de la asistencia","La aplicación de los valores a la práctica asistencial para orientar la decisión"],["Ese conjunto constituye la deontología, que fija un mínimo exigible más que un proceder de decisión.","Ese es el objeto de la responsabilidad profesional, que interviene después del acto.","Pone los valores a prueba de las situaciones reales para iluminar la elección del profesional."]],
  "42": ["¿Qué principios establece el juramento hipocrático para la relación asistencial?",["Actuar en el interés del paciente, no dañar y respetar la confidencialidad","Informar al paciente, recoger su acuerdo escrito y respetar su negativa","Declarar sus conflictos de interés, publicar sus resultados y formarse sin cesar"],["Esas tres exigencias forman la base ética que ese texto transmite a la práctica asistencial.","Esas exigencias proceden del reconocimiento moderno de la autonomía, muy posterior.","Esos deberes corresponden a la ética de la investigación y a los códigos contemporáneos."]],
  "43": ["¿Por qué se dice que la deontología y el derecho corresponden a una ética mínima?",["Solo atañen a un número muy pequeño de situaciones profesionales","Fijan el mínimo exigible, allí donde la ética busca la excelencia y la virtud","Carecen de toda sanción en caso de incumplimiento constatado"],["Su carácter mínimo depende del nivel de exigencia, no de la extensión de las situaciones cubiertas.","La conducta ética está sometida a una norma más estricta: constituye una ética máxima.","Son al contrario las únicas de esas disciplinas que van acompañadas de sanciones."]],
  "44": ["¿Cómo se influyen mutuamente la ética y la legislación?",["La legislación determina el contenido de la ética, que no es más que su aplicación","Ambas evolucionan cada una por su lado, sin encontrarse nunca","La ética inspira, la legislación encuadra, y la práctica pone a prueba a ambas"],["Eso sería ignorar que el reconocimiento de un valor precede y motiva la regla de derecho.","Al contrario, se influyen en un movimiento de ida y vuelta constante.","El consentimiento informado lo ilustra: respeto, dignidad y autonomía inspiraron la regla que lo vuelve obligatorio."]],
  "45": ["Un profesional juzga bueno informar a un allegado sin el acuerdo del paciente, para calmar su angustia. ¿De qué se trata?",["De una situación ética pero no legal","De una situación legal pero no ética","De un conflicto de valores entre dos profesionales"],["El profesional tiene la acción por justa, mientras que la ley no la protege o incluso la prohíbe.","Ese caso es el inverso: una conducta autorizada por la ley pero tenida por moralmente inaceptable.","El conflicto opone aquí el juicio del profesional a la regla de derecho, no a dos profesionales entre sí."]],
  "46": ["¿Qué permite la objeción de conciencia y con qué límite se topa?",["Rechazar todo acto que el profesional juzgue inoportuno, sin ninguna condición","Abstenerse de un acto legal contrario a sus convicciones, sin abandonar al paciente","Obtener que la ley se deje de lado para todos los profesionales de un centro"],["Se reconoce en casos limitados y nunca equivale al abandono del paciente.","Reconocida en casos limitados, no exime nunca de la continuidad de la asistencia ni del respeto de los derechos del paciente.","Es una posición individual, que no suspende la aplicación de la ley."]],
  "47": ["¿Por qué no puede limitarse la formación en ética al conocimiento de las normas?",["Las normas cambian demasiado a menudo para que sea útil aprenderlas","Las normas jurídicas no se aplican a los profesionales sanitarios","Hacen falta criterios de reflexión para actuar cuando la ley calla o es ambigua"],["El conocimiento de las normas sigue siendo indispensable: solo resulta insuficiente por sí solo.","Se les imponen plenamente; lo que está en cuestión es su insuficiencia en la situación concreta.","Principios bioéticos y códigos deontológicos aportan esas referencias allí donde la regla falta."]],
  "48": ["¿Cómo se define la bioética?",["El estudio de los problemas morales que plantea la investigación biológica y médica","El conjunto de las reglas disciplinarias impuestas a las profesiones sanitarias","El estudio de las consecuencias jurídicas de las nuevas prácticas biomédicas"],["Versa sobre los dilemas nacidos del desarrollo de las ciencias y técnicas aplicadas a lo vivo.","Esa definición corresponde a la deontología, que encuadra el ejercicio profesional.","El análisis jurídico acompaña a la bioética sin confundirse con su proceder moral."]],
  "49": ["¿Con qué perspectiva se concibió la bioética en su origen?",["Una disciplina destinada a encuadrar jurídicamente los ensayos clínicos","Un diálogo entre científicos y humanistas para preservar la humanidad","Una rama de la medicina legal que peritaba las faltas asistenciales"],["El encuadre de los ensayos corresponde a la regulación de la investigación, posterior y más estrecha.","Su visión inicial era ecologista: tender un puente hacia el futuro frente al consumo excesivo de recursos y a la degradación del medio ambiente.","El peritaje de las faltas corresponde a la responsabilidad profesional, no al proyecto bioético."]],
  "50": ["¿Por qué es la bioética una de las ramas más actuales de la ética?",["Es la única rama de la ética dotada de fuerza vinculante","Se limita a las cuestiones nacidas de la práctica clínica cotidiana","La técnica ha franqueado límites tenidos por infranqueables, lo que trastoca la moral"],["Sus dictámenes carecen por regla general de alcance obligatorio.","Es la ética clínica la que tiene ese alcance restringido; la bioética es mucho más amplia.","Las células madre lo ilustran: lo técnicamente posible obliga a reexaminar convenciones tenidas por inalterables."]],
  "51": ["¿Qué significa que la bioética sea civil o laica?",["Su método es independiente de toda religión y de todo sistema político","Excluye del debate a las personas con convicciones religiosas","Solo interviene en los centros del sector público"],["Su argumentación no extrae su validez de ninguna confesión ni de ningún poder.","Es pluralista y reconoce la pluralidad de los valores, incluidos los religiosos.","Su carácter laico califica su método, no su ámbito de aplicación institucional."]],
  "52": ["¿Cuál de estas características no corresponde a la bioética?",["Mediadora: resuelve los conflictos teniendo en cuenta los valores de cada uno","Dogmática: aplica verdades admitidas sin discusión posible","Procedimental: constituye un recorrido para reflexionar y decidir"],["La mediación entre los valores en presencia forma parte efectivamente de sus características.","Es al contrario racional y filosófica, por tanto argumentativa y deliberativa.","No es una simple reflexión teórica, sino un recorrido que conduce a la decisión."]],
  "53": ["¿Qué significa el carácter «de aplicación práctica» de la bioética?",["Solo se interesa por los gestos técnicos de la asistencia","Expone las posiciones en presencia sin concluir nunca","La deliberación tiene en ella por fin la toma de decisión"],["Su objeto abarca todas las interacciones humanas afectadas por las ciencias de la vida.","Quedarse sin conclusión contradiría precisamente su vocación práctica.","No se detiene en el análisis: debe desembocar en una conducta que seguir."]],
  "54": ["¿Cómo se reparte el trabajo en un proceder bioético interdisciplinar?",["Los científicos tratan los hechos, y las ciencias humanas estudian los valores","Los científicos zanjan a la vez los hechos y los valores en juego","Los juristas arbitran los desacuerdos entre científicos y filósofos"],["Esa articulación une el mundo empírico al mundo moral, lo que es propio de la bioética.","Encomendarles los valores equivaldría a suprimir la dimensión interdisciplinar.","El derecho encuadra la práctica, pero no desempeña ese papel de árbitro en la deliberación."]],
  "55": ["¿Qué distingue la ética clínica de la bioética en cuanto a su alcance?",["Una cubre la investigación y la política, y la otra se limita a la asistencia","Una se limita a la práctica asistencial, y la otra cubre ciencia y tecnología","Las dos tienen el mismo alcance y solo difieren en el vocabulario"],["La inversión es completa: es la bioética la que tiene el alcance más amplio.","La bioética abarca la vida, la salud, la biotecnología, la investigación y la política.","Difieren en el alcance, el nivel de análisis, el objetivo y el contexto."]],
  "56": ["¿En qué nivel de análisis se sitúa cada una de las dos disciplinas?",["La ética clínica en el nivel social, y la bioética en el caso particular","Ambas exclusivamente en el nivel de la institución asistencial","La ética clínica en el caso particular, y la bioética también en los niveles colectivos"],["Ese es exactamente el inverso del reparto entre las dos disciplinas.","El nivel institucional no es más que uno de los tres niveles de la bioética.","El caso clínico concreto es la unidad de análisis de una; la otra incluye lo institucional y lo social."]],
  "57": ["¿Cuáles son, para los profesionales sanitarios, los ámbitos más importantes de la bioética?",["La ética clínica y la ética de la investigación","La ética ambiental y la ética animal","La ética de los negocios y la ética de la comunicación"],["Son los dos campos con los que se encuentran directamente, junto al paciente y en los protocolos.","Esos campos corresponden a la bioética en sentido amplio, sin atañer a su práctica.","Esos ámbitos son ajenos a las ciencias de la vida a las que se aplica la bioética."]],
  "58": ["Entre los dilemas que plantea la inteligencia artificial, ¿cuál no se ha identificado?",["Los sesgos de los algoritmos, derivados de los datos con los que se entrenan","La desaparición programada de toda investigación biomédica realizada por humanos","La falta de fiabilidad de las herramientas, cuyos contenidos pueden estar fabricados"],["Esos sesgos agravan las desigualdades y penalizan más a los grupos ya marginados.","Las cuestiones recogidas versan sobre el empleo, los sesgos, la privacidad, la fiabilidad y la propiedad de los contenidos.","El riesgo de información engañosa forma parte de las preocupaciones identificadas."]],
  "59": ["¿Qué exigencias se imponen a los sistemas de inteligencia artificial en la Unión Europea?",["Ser supervisados por otros sistemas automatizados juzgados más eficaces","Ser desarrollados únicamente por centros públicos de investigación","Ser seguros, transparentes, trazables, no discriminatorios y vigilados por personas"],["Eso es precisamente lo que la norma descarta en favor de una supervisión humana.","Ninguna exigencia versa sobre el estatus jurídico del diseñador.","Se exige la supervisión humana en lugar de la automatización, para evitar resultados dañinos."]],
  "60": ["¿Cómo se define el transhumanismo?",["Un movimiento que propugna la superación de los límites físicos y psíquicos del hombre","Una corriente que rechaza toda intervención tecnológica sobre el cuerpo humano","Una doctrina que reserva las técnicas de reparación solo a las personas enfermas"],["Se basa en la idea de que la ciencia y la tecnología pueden conferir capacidades hasta ahora desconocidas.","Esa posición es exactamente la opuesta al proyecto transhumanista.","Limitar la técnica a la reparación equivale a rechazar la superación que reivindica."]],
  "61": ["¿Qué es un cíborg?",["Un dispositivo electrónico que reproduce el funcionamiento de un organismo","Un ser compuesto de materia viva y de dispositivos electrónicos","Un organismo vivo cuyo patrimonio genético se ha modificado"],["Un dispositivo enteramente artificial no comporta ninguna materia viva.","La definición asocia lo vivo y lo artificial en un mismo organismo.","La modificación genética no hace intervenir ningún dispositivo electrónico."]],
  "62": ["¿Qué estudia la neuroética?",["Las bases neurológicas de la conducta moral en el ser humano","La regulación del secreto médico aplicada a los datos cerebrales","El uso del razonamiento ético frente a las cuestiones nacidas de las neurociencias"],["Describir los mecanismos cerebrales del juicio moral es un objeto de investigación, no un proceder normativo.","Es una cuestión de protección de datos, que no agota el campo de la neuroética.","Versa sobre la investigación, las aplicaciones clínicas y no clínicas y la percepción pública de las neurociencias."]],
  "63": ["A propósito de los implantes neuronales, ¿qué distinción destaca la reflexión ética?",["Rehabilitar una capacidad perdida se admite, y mejorarla plantea cuestiones","La implantación se admite siempre que esté técnicamente dominada","La implantación está prohibida, incluso con fines de rehabilitación"],["La mejora plantea dudas sobre los efectos a largo plazo, el acceso y el riesgo de una subclase entre humanos mejorados y los demás.","El dominio técnico no resuelve la cuestión de la finalidad perseguida.","La rehabilitación de capacidades perdidas es precisamente el caso aceptado."]],
  "64": ["¿Cuál es el alcance de los dictámenes que emiten los comités de ética?",["Jurídicamente vinculantes para el conjunto de los centros sanitarios","No vinculantes, salvo en investigación, donde su aprobación condiciona el estudio","Simples opiniones sin ninguna consecuencia, incluso en materia de investigación"],["Sus conclusiones no tienen fuerza obligatoria, salvo en el caso de los comités de investigación.","No disponen de ningún poder normativo directo, con esa única excepción.","La aprobación de un comité de investigación es al contrario una condición esencial para el estudio."]],
  "65": ["¿Qué caracteriza a un comité de ética como instancia?",["Una jurisdicción especializada que zanja los litigios entre pacientes y profesionales","Un órgano de control que sanciona los incumplimientos deontológicos constatados","Un espacio de deliberación interdisciplinar que ilumina la toma de decisión"],["La resolución de los litigios corresponde a los tribunales, no a los comités de ética.","La sanción disciplinaria corresponde al colegio profesional.","La pluralidad de miradas permite analizar el dilema desde múltiples ángulos sin confiscar la decisión."]],
  "66": ["¿Qué particularidad distingue al comité internacional de bioética de las Naciones Unidas?",["Es el único organismo universal de reflexión sobre la bioética","Es el único comité cuyos dictámenes se imponen a los Estados que son miembros","Es el único comité compuesto exclusivamente por investigadores científicos"],["Sus miembros siguen los avances de la investigación en ciencias de la vida y velan por el respeto de los principios universales.","Como las demás instancias de ese tipo, formula dictámenes carentes de fuerza obligatoria.","Su composición es pluridisciplinar, a imagen del proceder bioético."]],
  "67": ["¿Cuál de estas misiones no corresponde al comité nacional de bioética español?",["Fijar los principios de los códigos de buenas prácticas de investigación científica","Autorizar la comercialización de los dispositivos médicos innovadores","Representar al país en los foros internacionales dedicados a la bioética"],["La definición de esos principios generales figura efectivamente entre sus misiones.","Esa autorización corresponde a las autoridades sanitarias competentes, no a una instancia consultiva.","Esa representación forma parte de sus atribuciones."]],
  "68": ["¿Cuál es el papel del comité consultivo nacional de ética en Francia?",["Autorizar o rechazar los protocolos de investigación en seres humanos","Juzgar los incumplimientos éticos cometidos por los profesionales sanitarios","Iluminar a los decisores y al debate público, a partir de las consultas que recibe"],["Esa autorización corresponde a los comités de protección de las personas.","Su carácter estrictamente consultivo excluye toda función jurisdiccional.","Organismo estrictamente consultivo, reflexiona sobre las cuestiones sociales nacidas de la evolución de las ciencias de la vida."]],
  "69": ["¿Qué garantiza la ley en la composición de esa instancia consultiva nacional?",["Una pluridisciplinariedad y un pluralismo que cruzan las miradas sobre cada cuestión","Una mayoría de profesionales sanitarios actualmente en ejercicio","Una representación igual de cada una de las confesiones religiosas"],["Es la diversidad de puntos de vista la que fundamenta la calidad del asesoramiento aportado.","No se prevé ningún predominio de una profesión; lo que se busca es la pluralidad.","El proceder es laico y se basa en un método independiente de toda religión."]],
  "70": ["¿En qué principios se basaba la ética médica tradicional?",["Respetar la autonomía y repartir equitativamente los recursos","No dañar y hacer el bien","Informar al paciente y recoger su consentimiento escrito"],["La autonomía es el más moderno de los principios y la justicia distributiva es posterior a esa tradición.","Exigidas primero a los médicos, esas dos reglas se han extendido a todos los profesionales de las ciencias médicas.","Esas obligaciones proceden del reconocimiento de la autonomía, ajeno a esa tradición."]],
  "71": ["¿Qué función cumplía el juramento hipocrático?",["Una regla impuesta a los médicos por la autoridad pública de su ciudad","Un contrato que vinculaba individualmente al médico con cada uno de sus pacientes","La más antigua autorregulación de la práctica en el seno mismo de la profesión"],["Su originalidad radica precisamente en que la profesión se daba a sí misma su regla.","Se trataba de un compromiso profesional general, no de un acuerdo cerrado paciente por paciente.","Buscaba evitar o atenuar las consecuencias indeseables de la práctica, y se ha desarrollado en los códigos actuales."]],
  "72": ["¿Qué provocó el nacimiento de la bioética moderna?",["Acontecimientos que mostraron que los principios fundamentales no se respetaban","La publicación de nuevos códigos de deontología por los colegios profesionales","La prolongación de la esperanza de vida en los países más desarrollados"],["Experimentos con presos y estudios realizados sin consentimiento alarmaron a científicos y humanistas.","Esos códigos acompañaron el movimiento sin ser su causa desencadenante.","Ese fenómeno presiona el reparto de los recursos, pero no está en el origen de la disciplina."]],
  "73": ["En el estudio sobre la sífilis realizado en Tuskegee, ¿qué incumplimientos se cometieron?",["Consentimiento recogido, pero sin información sobre la duración real del estudio","Ausencia de consentimiento, diagnósticos falsos y privación del tratamiento eficaz","Tratamiento correctamente administrado, pero resultados nunca publicados después"],["La ausencia total de consentimiento informado es precisamente lo que está en cuestión.","El reclutamiento se dirigió además a hombres muy pobres y poco instruidos, proclives a someterse a las figuras de autoridad.","La falta de tratamiento, a pesar de existir un remedio eficaz, constituye el núcleo del escándalo."]],
  "74": ["¿Cómo supieron los participantes de ese estudio que eran sus sujetos?",["Por una información individual que les entregaron los investigadores al final","Por una resolución judicial que los indemnizó antes del final del estudio","Por los medios de comunicación, décadas después del inicio del estudio"],["No se les facilitó ninguna información por parte del equipo de investigación.","La revelación pública precedió a todo reconocimiento del perjuicio.","No se les informó ni en el momento de la inclusión ni durante el desarrollo del estudio."]],
  "75": ["¿Qué caracteriza al estudio realizado en una escuela que acogía niños con discapacidad?",["Los niños fueron inoculados deliberadamente con un virus de la hepatitis","Los niños recibieron una vacuna experimental sin conocimiento de sus padres","Los niños fueron privados de los cuidados habituales que les correspondían"],["Se observaba después el efecto de un tratamiento; una protesta general obligó a detener el estudio.","No se trataba de una vacunación, sino de una inoculación deliberada del agente infeccioso.","El estudio versaba sobre una infección provocada, no sobre la privación de cuidados habituales."]],
  "76": ["¿Qué principios estableció el informe fundador de la ética de la investigación?",["El respeto de las personas, la beneficencia y la justicia","La autonomía, la no maleficencia, la beneficencia y la justicia","La beneficencia, la no maleficencia y el secreto profesional"],["El respeto de las personas engloba la autonomía y la protección de quienes no pueden ejercerla.","Esos cuatro principios forman el principialismo, formulado después a partir de ese informe.","El secreto es una obligación deontológica, no uno de los principios fundadores establecidos."]],
  "77": ["¿Qué es el principialismo?",["Una teoría completa que da por adelantado la solución de cada dilema","Un marco de cuatro principios que sirve para analizar los problemas morales de la asistencia","Un método que aplica la norma jurídica más protectora del paciente"],["Esos cuatro principios no constituyen una teoría, sino un marco metodológico.","Aporta los ingredientes iniciales del dilema ético y facilita su resolución concreta.","El enfoque es ético y deliberativo: no se reduce a la aplicación de una norma."]],
  "78": ["¿Qué significa que los cuatro principios sean «prima facie»?",["Están ordenados por importancia decreciente y se aplican en ese orden","Solo son recomendaciones carentes de carácter obligatorio","Obligan mientras no entren en conflicto, caso en el que se privilegia uno de ellos"],["Precisamente, no son objeto de ninguna jerarquización a priori.","Son vinculantes mientras no surja ningún conflicto entre ellos.","No se establece de antemano ninguna jerarquía ni prioridad entre ellos."]],
  "79": ["¿Cómo debe realizarse el arbitraje entre dos principios en conflicto?",["En la situación concreta, comparando los escenarios posibles","Aplicando una jerarquía de los principios fijada de una vez por todas","Remitiéndose al marco jerárquico del centro asistencial"],["La solución mejor o menos mala debe después asumirse y legitimarse con argumentos.","No se establece abstractamente ninguna jerarquía a priori entre los principios.","El arbitraje procede de una deliberación argumentada, no de una autoridad administrativa."]],
  "80": ["¿Cómo se define el principio de autonomía?",["La libertad del profesional de elegir la técnica que juzga más adecuada","La autodeterminación: el paciente decide libremente tras un intercambio de información","El derecho del paciente de exigir todo tratamiento que estime útil para él"],["La autonomía en cuestión es la del paciente, no la libertad terapéutica del profesional.","Su núcleo duro es un principio de autorización y de participación: se requiere su permiso para toda acción sobre su persona.","El principio fundamenta una autorización y una participación, no un derecho a exigir cualquier acto."]],
  "81": ["¿Qué capacidades supone el ejercicio de la autonomía?",["Una formación previa del paciente en las nociones médicas en juego","La mayoría de edad civil y la plena capacidad jurídica en todos los casos","Capacidades mentales como la comprensión y la intencionalidad"],["La información necesaria y suficiente la facilita el profesional; no se exige ninguna formación.","El menor maduro o la persona con medidas de apoyo participan en la medida de sus capacidades.","Sin comprensión de la información ni intención propia, la decisión no puede tenerse por autónoma."]],
  "82": ["¿Qué implica el respeto de la autonomía para el profesional?",["Informar suficientemente y verificar la comprensión y la libertad de la elección","Hacer firmar un documento antes de la intervención, sin otra formalidad","Dejar al paciente decidir solo, sin información que pueda influirle"],["Esa es la exigencia del consentimiento libre e informado, esencial tanto en la asistencia corriente como en investigación.","La firma no vale nada si no se verifican la comprensión y la libertad de la decisión.","La información es la condición misma de la autonomía, no una influencia que haya que evitar."]],
  "83": ["¿Cuál es el corolario del derecho a aceptar un tratamiento?",["El derecho a exigir en su lugar un tratamiento alternativo de su elección","El derecho a rechazarlo, incluso vital, salvo excepciones previstas por la ley","Ninguno: una vez informado, el paciente debe aceptar el tratamiento indicado"],["El corolario de la aceptación es el rechazo, no un derecho a exigir otra terapia.","Enfermedades contagiosas y hospitalización no voluntaria figuran entre las excepciones codificadas.","El rechazo informado es precisamente la contrapartida del consentimiento."]],
  "84": ["¿Qué es el paternalismo en salud?",["El profesional se abstiene de todo juicio para no influir en el paciente","La familia se sustituye al paciente para fijar la conducta que hay que seguir","El profesional decide el bien del paciente, con benevolencia pero con autoridad"],["Ese retraimiento es lo contrario del paternalismo, que se caracteriza por una decisión tomada en lugar del paciente.","El paternalismo designa la sustitución por el profesional, no por los allegados.","El principio de autonomía se le opone al hacer primar los valores y las preferencias del paciente, en virtud de su dignidad."]],
  "85": ["¿Qué lugar ocupa la autonomía entre los principios de la bioética?",["Es el más moderno de ellos","Es el más antiguo, ya presente en la medicina hipocrática","Es el que suscita menos empatía y menos incita a actuar"],["Introduce los valores del paciente en la deliberación y lo convierte en un actor principal de la asistencia.","Son la no maleficencia y la beneficencia las que se remontan a esa tradición.","Esa característica es la del principio de justicia."]],
  "86": ["¿Qué impone el principio de no maleficencia?",["Garantizar la ausencia de todo efecto adverso, incluso muy improbable","Evitar todo perjuicio inútil, desproporcionado o injustificado al paciente","Renunciar a todo acto que comporte una parte de riesgo para el paciente"],["No incluye los perjuicios no intencionales, como un efecto raro de un medicamento bien empleado.","Retoma la exigencia hipocrática de no dañar e impone que los beneficios prevalezcan sobre los riesgos.","Exige un balance favorable, no la abstención ante todo riesgo."]],
  "87": ["¿Cuál de estos perjuicios no entra en el ámbito de la no maleficencia?",["Un perjuicio causado por negligencia o por falta de conocimientos","Un perjuicio causado al poner otros valores por delante del paciente","Un efecto raro surgido con un medicamento indicado y correctamente utilizado"],["La negligencia y la incompetencia figuran entre las formas de causar un perjuicio.","Hacer primar consideraciones económicas o de reputación es un atentado directo contra el principio.","Los perjuicios no intencionales de ese tipo quedan expresamente excluidos del ámbito del principio."]],
  "88": ["¿Cómo zanjar entre «no dañar» y «aportar un beneficio» de riesgo incierto?",["Dar prioridad a la prevención del perjuicio","Dar prioridad al beneficio, al ser el riesgo por naturaleza incierto","Remitirse sistemáticamente a la elección que exprese el paciente"],["La prudencia se impone tanto más cuanto que el beneficio es dudoso o el perjuicio grave e irreversible.","La incertidumbre del beneficio es al contrario un motivo adicional de prudencia.","La elección del paciente corresponde a la autonomía y no resuelve por sí sola ese arbitraje."]],
  "89": ["¿A qué principio atenta la obstinación irrazonable?",["A la justicia, por la movilización excesiva de los recursos colectivos","A la no maleficencia, de la que constituye un incumplimiento frecuente","A la autonomía, por falta de recogida del consentimiento del paciente"],["El consumo de recursos es una consecuencia accesoria; el atentado primero recae sobre la ausencia de perjuicio.","El paciente incurable sufre en ella tratamientos que solo agravan dolorosamente el deterioro de su salud.","La obstinación puede producirse incluso con el acuerdo del paciente: lo que está en cuestión es el daño causado."]],
  "90": ["¿Cuál de estas conductas ilustra una acción no maleficente?",["Mantener un tratamiento ineficaz para no decepcionar al paciente","Aplicar una técnica contraindicada que el paciente reclama","Interrumpir una medicación reconocida como peligrosa para el paciente"],["Mantener un tratamiento sin beneficio expone al riesgo sin ninguna contrapartida.","Una técnica contraindicada nunca se vuelve aceptable, cualquiera que sea el contexto.","El profesional descarta un riesgo que no se compensaría con ningún beneficio demostrado."]],
  "91": ["¿En qué supera la beneficencia a la no maleficencia?",["Exige una acción positiva, y no la sola abstención de dañar","Impone no exponer al paciente a ningún riesgo, ni siquiera mínimo","Obliga a seguir en toda circunstancia la voluntad del paciente"],["El profesional debe promover activamente el bienestar, la salud y los intereses del paciente.","Esa exigencia absoluta correspondería a la no maleficencia, y aun así de forma excesiva.","El respeto de la voluntad procede de la autonomía, a veces en conflicto con la beneficencia."]],
  "92": ["¿Qué exige el principio de utilidad, componente de la beneficencia?",["Adoptar sistemáticamente la opción menos costosa para el centro","Comparar las alternativas y adoptar la mejor relación beneficio/riesgo","Adoptar la opción más reciente en el plano tecnológico disponible"],["El criterio es el beneficio para el paciente, no el ahorro conseguido.","No basta con querer hacer el bien: hay además que comparar las líneas de conducta posibles.","La novedad no garantiza una mejor relación entre beneficio y riesgo."]],
  "93": ["¿En qué condiciones se convierte la beneficencia en una obligación moral?",["Desde que el paciente formula una petición, cualquiera que sea su carga","Solo cuando el centro dispone de recursos excedentarios","Riesgo real, acción necesaria y eficaz, y beneficio superior al coste"],["El deber es modulable y está limitado por la proporcionalidad entre el coste y el beneficio.","El estado de los recursos modula el esfuerzo exigible sin condicionar la existencia de la obligación.","Esas tres condiciones reunidas transforman la posibilidad de actuar en deber de actuar."]],
  "94": ["¿Qué supone, para el profesional, dotarse de los medios para ser beneficente?",["Formarse de forma continua y apoyarse en la investigación que mejora la asistencia","Aceptar todas las peticiones de los pacientes para no dañarlos nunca","Delegar las decisiones complejas en un comité de ética competente"],["Ese es el vínculo directo con la noción de fisioterapia basada en la evidencia.","Acceder a toda petición puede al contrario conducir a actos sin beneficio demostrado.","El comité ilumina la decisión sin eximir al profesional de su deber de competencia."]],
  "95": ["¿Qué opone la no maleficencia y la beneficencia en cuanto a su nivel de exigencia?",["La primera se modula según los medios, y la segunda es absoluta","La primera es absoluta, y la segunda se modula según la carga y los recursos","Ambas se modulan igualmente según el contexto del centro"],["La inversión es completa: aplicar una técnica contraindicada sigue siendo siempre inaceptable.","No puede exigirse un esfuerzo ilimitado: el límite depende de la proporcionalidad entre coste y beneficio.","Solo la beneficencia se modula; la prohibición de dañar no admite ninguna adaptación."]],
  "96": ["¿De dónde nacen numerosos dilemas que oponen beneficencia y autonomía?",["El profesional se niega a facilitar la información debida al paciente","El centro limita el número de actos cubiertos por paciente","El paciente elige una opción que el profesional no juzga la más beneficiosa"],["La retención de información es un atentado directo contra la autonomía, no un conflicto entre dos principios.","Esa restricción pone en juego la justicia distributiva más que la beneficencia.","Ese desacuerdo constituye el terreno clásico del paternalismo."]],
  "97": ["¿Qué impone el principio de justicia en materia asistencial?",["Un acceso igual a los recursos, sin privilegio ni discriminación","Más recursos a los pacientes que más financian el sistema","Un trato estrictamente idéntico para todos, al margen de las necesidades"],["Se trata de una justicia distributiva, fundada en criterios racionales y no en la arbitrariedad.","Vincular el acceso a la contribución económica constituye precisamente una discriminación prohibida.","La igualdad buscada versa sobre el acceso y la consideración, y tiene en cuenta las necesidades de cada uno."]],
  "98": ["¿Por qué viola el principio de justicia prescribir una prueba no indicada?",["Expone al paciente a un riesgo desproporcionado para él mismo","Moviliza inútilmente recursos y retrasa el acceso de otros pacientes","Contraviene el consentimiento informado que ha dado el paciente"],["Ese razonamiento corresponde a la no maleficencia y no al reparto de los recursos.","El buen uso de los recursos públicos forma parte integrante de la exigencia de justicia.","El consentimiento puede haberse recogido sin que el atentado contra la justicia desaparezca."]],
  "99": ["¿Cuál de estas referencias no figura entre las reglas que orientan el principio de justicia?",["La regla de igualdad de oportunidades y el rechazo de la discriminación","La transparencia de las decisiones y el rechazo de los conflictos de interés","La prioridad a los pacientes cuyo pronóstico es más favorable"],["Esas dos referencias figuran explícitamente entre las reglas enunciadas.","La transparencia y la ausencia de conflictos de interés forman parte de las referencias establecidas.","Ese criterio de selección no figura entre las referencias, que excluyen toda discriminación."]],
  "100": ["¿A qué se llama microasignación?",["La decisión de atribuir un recurso limitado a un paciente y no a otro","El reparto del presupuesto de la salud entre las distintas regiones","La atribución de los créditos de investigación entre los equipos candidatos"],["Camas de cuidados intensivos u órganos disponibles vuelven difícil la igual consideración debida a cada uno.","Ese reparto de conjunto corresponde a las decisiones de política sanitaria, por tanto a la macroasignación.","Esa financiación no atañe a la distribución de la asistencia entre los pacientes."]],
  "101": ["¿Por qué suscita la justicia menos empatía y menos incita a actuar?",["Solo atañe a los responsables políticos y no a los profesionales","Se opone a menudo a la autonomía del paciente o al bien individual buscado","Es el más reciente de los cuatro principios de la bioética"],["Convoca a los profesionales sanitarios tanto como a la política sanitaria.","Tener en cuenta el coste para el grupo conduce a veces a limitar lo que sería deseable para un paciente.","Es la autonomía el más moderno de los principios."]],
  "102": ["En el cuadro que relaciona valores, principios y asistencia, ¿a qué corresponde la libertad?",["A la beneficencia y a la eficacia de la terapia aplicada","A la justicia, a la equidad y a la distribución de los recursos","A la autonomía, al modelo deliberativo y al consentimiento informado"],["La eficacia terapéutica responde a los valores de cuidado, humanización y calidad de vida.","La equidad y la correcta distribución responden a los valores de solidaridad e igualdad.","La libertad del paciente se traduce en su participación en la decisión y en la autorización que concede."]],
  "103": ["¿Qué es humanizar la asistencia sanitaria?",["Personalizar la asistencia centrándola en la persona que hay detrás de la enfermedad","Mostrar cordialidad y amabilidad con cada paciente atendido","Reducir los tiempos de espera y agilizar el recorrido por el centro"],["Eso supone abandonar la tendencia a tratar al paciente como una enfermedad.","La humanización va mucho más allá de la cordialidad: cambia la naturaleza misma de la relación.","La organización de los flujos no afecta a la consideración de la persona enferma."]],
  "104": ["¿A quién coloca la humanización de la asistencia en el centro de la organización?",["Solo al paciente, estando los demás actores al servicio de su atención","Al paciente, pero también al personal asistencial y a los acompañantes","Al equipo asistencial, cuyo bienestar condiciona la calidad de la asistencia"],["Reducir la humanización únicamente al paciente olvida al profesional y al acompañante.","Se trata de cuidar al paciente y al profesional, pues los allegados sufren a veces más que el enfermo.","El bienestar de los profesionales es necesario, pero no basta para definir el proceder."]],
  "105": ["¿Cuál es la herramienta fundamental de la humanización de la asistencia?",["La medición regular de la satisfacción mediante cuestionarios","La formación técnica continua del conjunto de los equipos asistenciales","La escucha activa de los profesionales a pacientes, familias y colegas"],["La recogida de indicadores no sustituye la escucha directa de las personas implicadas.","La competencia técnica se ha privilegiado precisamente en detrimento de la competencia humana.","Las asociaciones de pacientes, las familias convertidas en cuidadoras y los profesionales son los actores clave a los que hay que escuchar."]],
  "106": ["¿Cómo se describe la transformación de la persona en paciente?",["La vida se interrumpe, el decorado cambia y la identidad se pierde en unas horas","El paciente se adapta progresivamente a su nuevo papel a lo largo del ingreso","El paciente conserva sus referencias gracias a la presencia de sus allegados"],["El enfermo se convierte en «el paciente de la habitación 304», sin tiempo para adaptarse emocionalmente a ese papel.","La transformación se produce al contrario en unas horas, sin plazo de adaptación.","El cambio de decorado y la pérdida de identidad se producen a pesar del entorno."]],
  "107": ["¿Cuál de estas causas de deshumanización no se ha identificado?",["La presión institucional y el agotamiento profesional de los equipos","La disminución del número de actos técnicos que realizan los profesionales","La fragmentación del cuerpo y la desatención del sufrimiento del enfermo"],["El burnout figura entre las causas directamente identificadas.","Las causas señaladas son la medicalización excesiva, el agotamiento, la fragmentación y las jerarquías verticales.","Esa fragmentación se cita explícitamente entre las causas."]],
  "108": ["¿Qué consecuencias conlleva la deshumanización en fisioterapia?",["Aumento del número de sesiones necesarias y de los costes de la atención","Multiplicación de los conflictos entre los distintos profesionales del equipo","Pérdida del vínculo terapéutico, dolor más crónico y menor adherencia"],["El sobrecoste es una consecuencia indirecta y no se ha recogido entre los efectos descritos.","Las jerarquías verticales son una causa de deshumanización, no una de sus consecuencias.","El deterioro de la relación entre el fisioterapeuta y su paciente agrava la cronificación del dolor."]],
  "109": ["¿Qué papel desempeña la tecnología en la deshumanización?",["Mal empleada y sin intención humanizadora, se convierte en un obstáculo para una asistencia humana","Humaniza mecánicamente la asistencia al liberar tiempo para la relación","No tiene efecto sobre la calidad relacional, que depende únicamente del profesional"],["La asistencia se ha vuelto cada vez más técnica, en detrimento de las relaciones interpersonales.","El tiempo liberado no se ha reinvertido en la relación, y la asistencia se ha mecanizado al contrario.","El lugar que ocupa la técnica condiciona directamente la calidad de la relación."]],
  "110": ["¿Cuál de estos menoscabos no figura entre las formas en que se compromete la dignidad?",["La dependencia de otros para realizar las actividades más elementales","La dificultad de obtener una cita en un plazo razonable","La reducción de la persona a un diagnóstico o a un número de habitación"],["Esa dependencia figura entre los menoscabos directamente descritos.","Los menoscabos recogidos son la pérdida de intimidad, la dependencia, la despersonalización y la pérdida de poder de decisión.","La despersonalización es uno de los menoscabos centrales de la dignidad."]],
  "111": ["¿Qué beneficios han demostrado las estrategias de humanización?",["Una reducción del número de profesionales necesarios por servicio","Un aumento del número de pacientes tratados cada día","Menos ansiedad y dolor, recuperación acelerada y personal más fidelizado"],["No se asocia ninguna disminución de plantilla a esas estrategias.","El objetivo perseguido no es el rendimiento, sino la calidad de la experiencia y de los resultados.","El consumo de medicamentos también disminuye, en un sector donde el absentismo es el más elevado."]],
  "112": ["¿Qué destaca la ética del «care» como eje de la moralidad?",["La relación, la interdependencia y la responsabilidad emocional","La aplicación rigurosa de principios universales a cada situación","La maximización del beneficio colectivo obtenido con los recursos empleados"],["Cuidar es tomar las preocupaciones y las necesidades del otro como base de la acción.","Ese enfoque por principios es el del principialismo, no el de la ética del care.","Ese razonamiento utilitarista es ajeno a la lógica relacional del care."]],
  "113": ["¿Qué distinción introduce la ética del care?",["Tratar corresponde al profesional, y cuidar corresponde exclusivamente a la familia","Tratar corresponde a la tradición terapéutica, y cuidar alivia el sufrimiento","Tratar atañe al cuerpo, y cuidar atañe únicamente al psiquismo"],["El acompañamiento forma parte integrante del papel del profesional.","No se trata solo de tratar, sino también de acompañar y de sostener.","La distinción no coincide con el reparto entre lo físico y lo psíquico."]],
  "114": ["¿Qué fase de la atención corresponde a la toma de conciencia de la necesidad?",["Taking care of: asumir la responsabilidad de los cuidados que hay que organizar","Care giving: realizar concretamente el trabajo de cuidado junto al paciente","Caring about: preocuparse por el otro y percibir la necesidad de cuidar"],["Esa fase sigue a la toma de conciencia y corresponde al principio de responsabilidad.","Esa fase es la de la realización, a la que responde el principio de competencia.","Es la primera de las cuatro fases, de la que se deriva el principio ético de atención."]],
  "115": ["¿A qué fase corresponde la reacción de la persona atendida?",["Care receiving, a la que responde el principio de capacidad de respuesta","Care giving, a la que responde el principio de competencia","Caring about, a la que responde el principio de atención"],["Esa reacción permite evaluar si la atención ha sido adecuada y ajustar el tratamiento.","Esa fase designa el trabajo concreto de cuidado, no la respuesta del paciente.","Esa fase es la de la toma de conciencia inicial de la necesidad."]],
  "116": ["¿Qué abarca el «caring with» en la aplicación del modelo en fisioterapia?",["Aplicar las técnicas manuales con seguridad y profesionalidad","Promover la equidad de acceso, trabajar en equipo y volver al paciente corresponsable","Recoger la vivencia del paciente para ajustar las cargas de ejercicio"],["Esa exigencia corresponde al care giving y al principio de competencia.","Esa dimensión remite a los valores de solidaridad y de justicia.","Esa respuesta corresponde al care receiving y a la capacidad de respuesta."]],
  "117": ["¿Cómo se concibe la vulnerabilidad en la relación clínica?",["Como un estado propio del paciente, que el profesional debe compensar","Como una debilidad pasajera ligada únicamente al momento del ingreso","Como una condición humana compartida, que afecta también al terapeuta"],["Limitar la vulnerabilidad al paciente desconoce la del profesional.","Es una condición humana duradera, exacerbada por el sufrimiento y la pérdida de autonomía.","Inseguridad, impotencia y agotamiento emocional vuelven vulnerable al profesional a su vez."]],
  "118": ["¿Cómo se define la compasión en la relación asistencial?",["Una empatía activa acompañada del deseo de aliviar el sufrimiento","Un sentimiento de lástima experimentado ante la angustia de la persona enferma","Un distanciamiento emocional que protege al profesional del agotamiento"],["Exige presencia, autorregulación y apertura emocional, y no se confunde con la lástima.","La compasión se distingue precisamente de la lástima, que coloca al otro en posición de inferioridad.","La compasión supone al contrario una apertura emocional controlada."]],
  "119": ["¿Qué implica el respeto relacional más allá del consentimiento formal?",["Recoger sistemáticamente el acuerdo escrito antes de cada acto realizado","Reconocer la dignidad, las necesidades, los límites y las opiniones sin juzgar","Abstenerse de todo intercambio personal para preservar la neutralidad"],["Ese es precisamente el consentimiento formal que el respeto relacional supera.","El respeto en la asistencia supera la simple formalidad de la autorización firmada.","La neutralidad distante priva a la relación del reconocimiento que exige."]],
  "120": ["¿Por qué es crucial el primer contacto con el paciente?",["Permite recoger lo esencial de los datos administrativos de la historia","Permite anunciar de entrada el pronóstico para evitar falsas expectativas","Permite crear la relación personal en la que se apoyan el diagnóstico y la asistencia"],["La recogida administrativa no tiene ningún alcance sobre la calidad del vínculo terapéutico.","Las expectativas se trabajan a lo largo de la relación, no mediante un anuncio inicial.","La comodidad que siente el paciente hacia el profesional condiciona el establecimiento de un vínculo de confianza."]],
  "121": ["¿Cuáles son las tres dimensiones de la relación terapéutica?",["Los objetivos, las actividades para alcanzarlos y el vínculo entre las dos personas","El diagnóstico, el tratamiento aplicado y la evaluación final de los resultados","La información facilitada, el consentimiento recogido y el secreto garantizado"],["Objetivos negociados, tareas acordadas y vínculo afectivo recíproco forman la relación.","Esa secuencia describe el proceder clínico, no la relación terapéutica.","Esas tres obligaciones son jurídicas y no constituyen las dimensiones del vínculo."]],
  "122": ["¿En qué se apoya el vínculo entre el fisioterapeuta y su paciente?",["Una relación estrictamente funcional limitada a la ejecución de los cuidados","Un vínculo afectivo mutuo fundado en el respeto, la confianza y la aceptación","Una autoridad del profesional que el paciente acepta y a la que se ajusta"],["La asistencia humanizada supone abandonar las relaciones funcionales en favor de relaciones personales.","Es un elemento fundamental del trabajo terapéutico, junto con los objetivos y las tareas.","La relación de autoridad vertical figura entre las causas de deshumanización."]],
  "123": ["¿Cuáles son las expectativas más frecuentes de los pacientes?",["La rapidez de la atención y el control del coste del tratamiento","El acceso a las técnicas más recientes y a los mejores equipos","La curación, la comprensión, la información y los cuidados"],["Esas preocupaciones existen, pero no figuran entre las expectativas recogidas.","La demanda tecnológica no está en el primer plano de las expectativas expresadas.","Esas expectativas son a veces irrealistas, lo que suscita temores que el profesional deberá calmar."]],
  "124": ["¿Cómo se manifiesta el miedo a ser juzgado o incomprendido en un paciente?",["Puede ocultar información o adoptar conductas defensivas","Se vuelve exigente y desconfiado con el equipo que lo atiende","Se bloquea, se vuelve irritable o se instala en la negación de su enfermedad"],["Esa ocultación perjudica directamente la calidad de la evaluación y de la atención.","Esa conducta refleja más bien el temor de que se le oculte información.","Esas reacciones se relacionan con el temor de que el estado sea incurable."]],
  "125": ["¿Qué riesgo comportan las conductas de dependencia en el paciente?",["Rechaza los cuidados propuestos e interrumpe prematuramente el tratamiento","Su autonomía queda anulada y aparecen conductas regresivas","Cuestiona sistemáticamente las decisiones que toma el profesional"],["El rechazo corresponde más bien a la negación o a la desconfianza que a la dependencia.","La necesidad de ser atendido se satisface a costa de la capacidad de decisión del paciente.","El cuestionamiento refleja la desconfianza, no la dependencia."]],
  "126": ["¿Qué designa la comunicación paraverbal?",["Los gestos, los movimientos y el contacto visual entre los interlocutores","Las palabras empleadas, que siempre requieren una interpretación","La manera en que se dicen las cosas: tono, velocidad, timbre y silencios"],["Esos elementos corresponden a la comunicación no verbal.","Las palabras constituyen la comunicación verbal propiamente dicha.","Se distingue tanto de las palabras mismas como de los gestos que las acompañan."]],
  "127": ["¿Cuál es la particularidad de la comunicación humana?",["Es multimodal y simultánea, y los tres registros operan al mismo tiempo","Es secuencial, y cada registro interviene a su turno en el intercambio","Es esencialmente verbal, y los demás registros son solo accesorios"],["Verbal, paraverbal y no verbal se producen conjuntamente y se influyen mutuamente.","Los medios utilizados se producen al mismo tiempo y no sucesivamente.","Lo que se hace modifica la interpretación de lo que se dice: los demás registros son determinantes."]],
  "128": ["¿Qué caracteriza al modelo paternalista de relación terapéutica?",["El profesional facilita toda la información y ejecuta la elección del paciente","El profesional elige lo que juzga mejor e informa de forma selectiva","El profesional clarifica los valores del paciente sin juzgarlos ni discutirlos"],["Ese es el modelo informativo, en el que el profesional actúa como técnico experto.","Su papel es el de un tutor; el modelo supone un criterio objetivo de lo mejor que el paciente asume.","Ese es el modelo interpretativo, en el que el profesional es consultor y consejero."]],
  "129": ["¿En qué situación conserva interés el modelo paternalista?",["En las atenciones prolongadas, en las que ahorra tiempo de intercambio","En los casos en que el paciente tiene un buen conocimiento de su patología","En las situaciones que ponen la vida en peligro, en las que permite actuar rápido"],["La duración de la atención no justifica decidir en lugar del paciente.","Un paciente informado es precisamente aquel para quien ese modelo conviene menos.","Fuera de esas situaciones, reduce la autonomía del paciente."]],
  "130": ["¿Qué caracteriza al modelo informativo?",["El paciente conoce sus valores pero no los hechos; elige, y el clínico ejecuta","El paciente ignora sus valores, que el profesional debe ayudarle a clarificar","Los valores del paciente se discuten y se revisan con el profesional"],["El papel del profesional es el de un técnico experto, proveedor de información, lo que aumenta la autonomía.","Esa situación corresponde al modelo interpretativo.","Esa discusión moral caracteriza al modelo deliberativo."]],
  "131": ["¿Cuál es el papel del profesional en el modelo interpretativo?",["Tutor: determina lo que es mejor y conduce al paciente a consentirlo","Consultor y consejero: clarifica los valores del paciente sin juzgarlos","Docente y guía: acompaña al paciente en un debate moral"],["Ese papel de tutor define el modelo paternalista.","Propone después las opciones que más respetan esos valores, y el paciente elige.","Ese papel corresponde al modelo deliberativo."]],
  "132": ["¿Qué distingue el modelo deliberativo de los demás modelos?",["En él el profesional ejecuta sin discusión la elección que expresa el paciente","En él el profesional interpreta los valores del paciente sin discutirlos nunca","En él los valores del paciente quedan abiertos a la discusión y a la revisión"],["Esa ejecución sin debate caracteriza al modelo informativo.","La interpretación sin discusión define el modelo interpretativo.","La autonomía se concibe en él como un desarrollo moral de uno mismo, y el profesional actúa como docente y guía."]],
  "133": ["¿Por qué se considera ideal el modelo deliberativo en numerosos contextos?",["Favorece a la vez la autonomía del paciente y la calidad de las intervenciones","Es el más rápido de aplicar en la práctica cotidiana","Exime al profesional de tener que justificar sus recomendaciones"],["Exige en contrapartida tiempo y formación, lo que a veces limita su uso.","Requiere al contrario tiempo, lo que constituye su principal límite.","Supone al contrario un debate moral argumentado con el paciente."]],
  "134": ["¿Basta respetar la ley y el código deontológico para ejercer de manera ética?",["No: eso no implica que la práctica sea conforme a la ética","Sí: el código y la ley definen enteramente el ejercicio ético","Sí, siempre que el profesional los conozca perfectamente"],["El ejercicio ético supone integrar la reflexión en las propias actitudes, el lenguaje y las interacciones.","La legislación fija los mínimos; la ética aspira a los máximos deseables.","El conocimiento de los textos no garantiza el compromiso ético del profesional."]],
  "135": ["¿Cuál de estos principios europeos completa los principios de la bioética?",["La proporcionalidad, que limita el esfuerzo exigible al profesional","La integridad, que protege la inviolabilidad del cuerpo humano","La continuidad, que impone no interrumpir nunca una atención"],["Esa modulación corresponde a la beneficencia, no a los principios europeos enumerados.","Por eso el consentimiento es esencial antes de toda intervención sobre el paciente.","La continuidad de la asistencia es una obligación deontológica distinta de esos principios."]],
  "136": ["¿Qué abarca el principio europeo de sinceridad y honestidad?",["Declarar al paciente los conflictos de interés que mantiene el profesional","Reconocer sus errores ante el equipo y ante la jerarquía","Dar al paciente y a su familia la información necesaria para decidir"],["La declaración de conflictos de interés es una obligación distinta de ese principio.","La confesión de los errores corresponde a la responsabilidad profesional, no a ese principio.","Es esencial en la comunicación entre el profesional y quienes deben pronunciarse."]],
  "137": ["¿Qué es un problema ético?",["Una situación en la que un valor o un principio se pone en cuestión","Una situación en la que dos principios se oponen y obligan a elegir","Una situación en la que el profesional conoce la solución pero no puede actuar"],["La discriminación en la asistencia sanitaria constituye un ejemplo.","Esa oposición caracteriza el dilema ético, mucho más complejo de resolver.","Esa imposibilidad de actuar define la angustia moral."]],
  "138": ["¿Qué caracteriza un dilema ético?",["Un valor se vulnera y hay que restablecer el principio desconocido","Dos principios se oponen y hay que elegir entre dos opciones ambas justas","El profesional duda entre una solución ventajosa y una solución justa"],["La puesta en cuestión de un solo valor define el problema ético.","Es una decisión entre «lo que es justo y lo que es justo», mucho más compleja que un problema ético.","Ese arbitraje corresponde a la tentación moral."]],
  "139": ["¿Qué es una situación de angustia moral?",["El profesional ignora qué conducta adoptar ante una situación inédita","El profesional sabe que hay valores amenazados pero elige ignorarlos","El profesional conoce la solución correcta pero unos obstáculos le impiden actuar"],["La incertidumbre sobre la solución no está en cuestión: la solución se conoce.","Ese retraimiento voluntario define la situación de silencio.","Esos obstáculos son externos, como la política de la institución, o internos, como el miedo o la inseguridad."]],
  "140": ["¿Cuál de estos obstáculos a la acción es un obstáculo interno?",["La inseguridad y el miedo que experimenta el propio profesional","La falta de tiempo que impone la organización del servicio","La burocracia excesiva y las normas internas del centro"],["La falta de sensibilización corresponde igualmente a los obstáculos internos.","La falta de tiempo es un obstáculo externo ligado a la institución.","Esas restricciones institucionales son obstáculos externos."]],
  "141": ["¿Qué es una situación de tentación moral?",["Hay que elegir entre dos opciones igualmente defendibles en el plano moral","Hay que elegir el bien antes que el mal, pero el mal procura una ventaja","Hay que actuar cuando la institución impide poner en práctica la solución"],["Esa equivalencia entre dos opciones justas caracteriza el dilema.","Es la ventaja personal esperada la que crea la tentación.","Ese impedimento exterior corresponde a la angustia moral."]],
  "142": ["¿Qué hace el profesional en una situación de silencio?",["Reconoce la conducta correcta pero se topa con obstáculos concretos","Elige el mal porque obtiene de él un beneficio personal directo","Sabe que hay valores en cuestión pero elige no tomar partido"],["Esa impotencia pese a la voluntad de actuar define la angustia moral.","Ese cálculo corresponde a la tentación moral.","Prefiere ignorar el problema antes que intervenir."]],
  "143": ["¿Por qué se afirma que toda toma de decisión es también una decisión ética?",["Porque la voluntad del paciente y sus preferencias deben tenerse siempre en cuenta","Porque cada decisión compromete la responsabilidad jurídica del profesional","Porque las políticas institucionales encuadran todas las decisiones que se toman"],["Las decisiones se apoyan en los datos científicos y en la experiencia, pero nunca al margen de la voluntad del paciente.","La responsabilidad jurídica es una consecuencia posible, no el fundamento de la afirmación.","Esas políticas son uno de los factores de la decisión, y no su dimensión ética."]],
  "144": ["¿Qué actitud se impone frente a los conflictos éticos, que son inevitables?",["Disolverlos para restablecer rápidamente la cohesión del equipo","Minimizarlos y resolverlos, sin buscar nunca disolverlos","Comunicarlos sistemáticamente a la dirección del centro"],["Disolver el conflicto equivale a negar su existencia en lugar de tratarlo.","Comprender la realidad del conflicto para tratarlo así constituye un imperativo moral.","La comunicación jerárquica no constituye la respuesta esperada."]],
  "145": ["¿En qué consiste el método deliberativo?",["Aplicar el principio que prevalece según una jerarquía preestablecida","Recoger la opinión del más experimentado de los miembros del equipo asistencial","Analizar los hechos, identificar las acciones posibles y después elegir la acción óptima"],["No se establece ninguna jerarquía a priori entre los principios en presencia.","La deliberación supone la confrontación de puntos de vista múltiples, no la autoridad de uno solo.","El razonamiento deliberativo es un proceso orientado a la toma de decisión."]],
  "146": ["¿Cuál es el alcance del razonamiento deliberativo?",["No aporta ninguna certeza y admite varias soluciones razonables","Desemboca en una solución única, demostrada como la única prudente","Garantiza que la decisión tomada será jurídicamente inatacable"],["Sigue siempre afectado por la incertidumbre, sin que la pluralidad de soluciones las vuelva imprudentes.","Es compatible con la pluralidad de soluciones a un mismo problema.","La conformidad con el derecho se verifica por separado, mediante la prueba de legalidad."]],
  "147": ["¿Qué requiere la deliberación con personas de puntos de vista diferentes?",["Mantenerse firmemente en su posición inicial para alimentar el debate","Una gran capacidad de escucha y de autoanálisis, y relativizar su punto de vista","Apartarse ante la opinión del participante más experimentado del grupo"],["Relativizar su propio punto de vista es precisamente lo que enriquece el proceder.","Discutir racionalmente las posiciones de los demás conduce a hacer evolucionar la propia visión del proceso.","La deliberación pone en interacción los puntos de vista, sin privilegiar ninguno de antemano."]],
  "148": ["¿Qué son las acciones extremas en el método deliberativo?",["Las que concilian mejor los valores en conflicto en la situación","Las que son manifiestamente ilegales y deben descartarse de entrada","Las que, al elegir un principio, sacrifican completamente el otro"],["Esas son al contrario las acciones intermedias, situadas entre los dos extremos.","El examen de la legalidad interviene en la fase de las pruebas de coherencia.","Sirven para enmarcar las acciones intermedias al identificar los límites que hay que rechazar."]],
  "149": ["¿Cuál es la acción óptima al término de la deliberación?",["La que menos daña los valores en conflicto y es la más prudente","La que respeta íntegramente el principio más importante en juego","La que obtiene la adhesión unánime de los miembros del grupo"],["Tiene en cuenta las circunstancias y las consecuencias; el mejor plan coincide con el más prudente.","Sacrificar el otro principio caracteriza una acción extrema, no la acción óptima.","La unanimidad no es el criterio: lo es la prudencia respecto a los valores."]],
  "150": ["¿Qué pruebas de coherencia hay que aplicar a la decisión adoptada?",["Eficacia, coste y aceptabilidad por la institución asistencial implicada","Estabilidad en el tiempo, publicidad y legalidad de la conducta elegida","Conformidad con el código deontológico y acuerdo del supervisor asistencial"],["Esos criterios de gestión no figuran entre las pruebas de coherencia.","Se verifica que se volvería a adoptar más adelante, que se defendería públicamente y que es conforme al derecho.","La prueba de legalidad cubre el derecho, sin exigir el acuerdo de la jerarquía."]],
  "151": ["¿Qué verifica la prueba de estabilidad en el tiempo?",["Si la decisión seguirá siendo aplicable a pesar de la evolución de la legislación","Si el estado del paciente permitirá mantener la conducta elegida","Si se tomaría la misma decisión tras cierto tiempo de distancia"],["La prueba no versa sobre la perdurabilidad jurídica de la solución.","La evolución clínica no es el objeto de esa prueba.","Permite evaluar si la decisión se tomó bajo la influencia de las emociones que suscitó el caso."]],
  "152": ["En el proceso de decisión, ¿a qué principio remite la pregunta «¿qué no hay que hacer en ningún caso?»",["A la no maleficencia","A la beneficencia","A la justicia"],["Esa pregunta abre el proceso al fijar de entrada lo que queda excluido.","La beneficencia responde a la pregunta de qué es lo mejor para el paciente.","La justicia responde a qué dañaría gravemente a la sociedad o a terceros."]],
  "153": ["¿Qué conflictos éticos genera la creciente complejidad de la asistencia?",["Únicamente entre el profesional y el paciente que atiende","Entre profesionales, con el paciente, con la familia o con el centro","Únicamente entre los distintos profesionales de un mismo equipo"],["Los conflictos recogidos implican también a las familias, a los equipos y a la institución.","El propio paciente puede entrar igualmente en conflicto con la institución que lo atiende.","Esa es solo una de las cinco configuraciones identificadas."]],
  "154": ["¿Qué ventaja ofrece el consultor en ética clínica respecto al comité?",["Un poder de decisión vinculante para el equipo que lo solicita","Una competencia jurídica que permite validar la legalidad del acto","Más proximidad y capacidad de reacción, lo más cerca posible de la práctica cotidiana"],["Como el comité, ilumina la decisión sin sustituir a los profesionales.","Su ámbito es la ética clínica, no el peritaje jurídico.","Localizable de forma permanente, permite tratar un conflicto urgente sin esperar una reunión formal."]],
  "155": ["¿En qué servicios resulta más útil recurrir a un consultor en ética?",["En los de alta carga ética: cuidados intensivos, urgencias, oncología y paliativos","En los servicios de consulta externa con alto volumen de pacientes","En los servicios administrativos encargados de la gestión de los ingresos"],["Los conflictos frecuentes versan allí sobre la capacidad del paciente, la futilidad y la limitación del esfuerzo terapéutico.","El volumen de actividad no determina la densidad de los conflictos éticos.","Esos servicios no toman decisiones clínicas que impliquen conflictos de valores."]]
});
